using System;

// The same template for 0-4 parameters; keep them in sync.

/// <summary>
/// A Signal of a <see cref="SchematicBehavior"/>. Declare it as a field:
/// <code>public readonly SignalHandle Example;</code>
/// No initializer is needed: the field is bound when the Behavior is created, and its Signal asset is generated by the editor.
/// Signals are addressed to a spawned Schematic Object by its UID, so Behaviors and Schematic Graphs on the same object
/// send to and hear each other. <see cref="Invoke()"/> and <see cref="Subscribe(Action)"/> use the Behavior's
/// selected instance; the overloads taking a <see cref="BehaviorInstance"/> target one explicitly.
/// </summary>
public readonly struct SignalHandle : ISignalHandle
{
    private readonly BehaviorSignal _signal;

    internal SignalHandle(BehaviorSignal signal) { _signal = signal; }

    BehaviorSignal ISignalHandle.Signal => _signal;
    public bool IsDefined => _signal != null;
    /// <summary>The Signal asset, which Schematic Graph nodes reference.</summary>
    public SignalData Data => Definition.Data;

    private BehaviorSignal Definition => _signal ?? throw new InvalidOperationException("This SignalHandle isn't bound to a Behavior. Only SignalHandle fields of a SchematicBehavior are bound.");

    /// <summary>Sends the Signal to the selected instance's object.</summary>
    public void Invoke()
    {
        var signal = Definition;
        signal.Data.Invoke(signal.SelectedUID);
    }

    /// <summary>Sends the Signal to the given instance's object.</summary>
    public void Invoke(BehaviorInstance target)
        => Definition.Data.Invoke(BehaviorSignal.UIDOf(target));

    /// <summary>Sends the Signal to the object with the given UID; 0 reaches every instance.</summary>
    public void Invoke(int uid)
        => Definition.Data.Invoke(uid);

    /// <summary>Listens for the Signal on the selected instance's object.</summary>
    public SignalSubscription Subscribe(Action handler)
        => Subscribe(Definition.SelectedUID, handler);

    /// <summary>Listens for the Signal on the given instance's object.</summary>
    public SignalSubscription Subscribe(BehaviorInstance target, Action handler)
        => Subscribe(BehaviorSignal.UIDOf(target), handler);

    /// <summary>Listens for the Signal on the object with the given UID; 0 listens to every instance.</summary>
    public SignalSubscription Subscribe(int uid, Action handler)
        => SignalRouting.Subscribe(Definition.Data, uid, handler);

    internal static Type[] ParameterTypes => Type.EmptyTypes;
}

